function incrementDecimalString(numStr) {
  const digits = numStr.split('')
  let carry = 1
  for (let i = digits.length - 1; i >= 0 && carry; i--) {
    const sum = Number(digits[i]) + carry
    if (sum >= 10) {
      digits[i] = '0'
      carry = 1
    } else {
      digits[i] = String(sum)
      carry = 0
    }
  }
  if (carry) digits.unshift('1')
  return digits.join('')
}

function normalizeDecimalString(valueStr, min, max) {
  const isNegative = valueStr.startsWith('-')
  const normalized = isNegative ? valueStr.slice(1) : valueStr
  let [intPart, decPart = ''] = normalized.split('.')
  intPart = intPart || '0'

  if (max === 0) {
    if (decPart && Number(decPart[0]) >= 5) {
      intPart = incrementDecimalString(intPart)
    }
    decPart = ''
  } else if (decPart.length > max) {
    const keep = decPart.slice(0, max)
    const roundDigit = decPart[max]
    if (roundDigit >= '5') {
      const rounded = incrementDecimalString(keep)
